def parse_nonnegative(text):
    value = int(text)
    if value < 0:
        raise ValueError("Value must be nonnegative")
    return value

for text in ["12", "bad", "-3"]:
    try:
        value = parse_nonnegative(text)
    except ValueError as error:
        print(f"Invalid input: {error}")
    else:
        print(f"Accepted: {value}")
